{
  "schemaVersion": "0.2",
  "slug": "nav-account-card",
  "name": "NavAccountCard",
  "family": "B",
  "status": "experimental",
  "purpose": "Official Navigation sidebar foot: avatar | username/nickname | logout. Mount in Navigation footer / #footer — not AppShell footer.",
  "scenarios": [
    "Pin account identity and a logout control at the bottom of the Navigation sidebar rail",
    "Replace the default collapse toggle as the product foot chrome when an account foot is present",
    "Keep the account card hidden on compact TabBar (<48rem)"
  ],
  "props": {
    "username": {
      "type": "string",
      "required": true,
      "description": "Primary display name."
    },
    "nickname": {
      "type": "string",
      "required": false,
      "description": "Optional secondary line."
    },
    "avatarSrc": {
      "type": "string",
      "required": false,
      "description": "Avatar image URL."
    },
    "avatarFallback": {
      "type": "string",
      "required": false,
      "description": "Avatar fallback glyph; defaults to the first letter of username."
    },
    "logoutLabel": {
      "type": "string",
      "required": false,
      "description": "Logout control label and accessible name.",
      "default": "Log out"
    },
    "onLogout": {
      "type": "event",
      "required": false,
      "description": "Fired when logout is activated. Vue: logout.",
      "payload": "() => void"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Expanded account row with name and logout."
    }
  ],
  "composition": {
    "allowedParents": ["navigation"],
    "allowedChildren": ["avatar", "button", "text"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not mount NavAccountCard on the compact TabBar — Navigation hides __footer below 48rem.",
    "Do not put this in AppShell footer; that slot is credits/legal via Footer.",
    "Do not use the logout control as a collapse toggle — rail density stays on collapsible API.",
    "Do not invent a consumer cu- NavAccountCard pretending to be a library export."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": ["Tab to logout; Enter/Space activates logout"],
    "focus": "Logout is one tab stop; avatar is decorative when alt matches username.",
    "labeling": "Logout uses logoutLabel as aria-label; avatar alt is username.",
    "wcag": ["1.3.1", "2.1.1", "4.1.2"]
  },
  "responsive": {
    "strategy": "Card itself is not breakpoint-aware. Visibility is owned by Navigation: sidebar/rail shows __footer; compact TabBar hides it. Collapsed rail hides name text via CSS.",
    "breakpoints": {
      "compact": "Must not present NavAccountCard — Navigation __footer is display:none.",
      "medium": "Visible in Navigation footer; collapsed rail shows avatar + icon logout.",
      "large": "Visible in Navigation footer with full name row."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical flex row; logout sits on the inline-end via margin-inline-start:auto.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "nav-account-card",
    "states": ["default"],
    "intents": ["identify-user", "sign-out"]
  },
  "mechanics": "Export NavAccountCard and place it in Navigation footer / #footer — not AppShell footer (that is Footer/credits). When footer is set, Navigation does not render the collapse toggle. logoutLabel defaults to Log out. Chrome row height matches NavigationTitle: min-block-size calc(var(--cu-control-size-active) + 2 * var(--cu-space-1)). Scroll contract: only __list scrolls; header and footer stay pinned. Compact TabBar hides __footer.",
  "usage": [
    "Import NavAccountCard from @chameleon-ui/components-react or the React/Vue umbrella.",
    "Pass as Navigation footer (React) or #footer (Vue) — never AppShell footer.",
    "Bind onLogout / @logout for sign-out; do not reuse this button for rail collapse.",
    "Do not hardcode rem row heights; densify via --cu-control-size-active."
  ],
  "exports": [
    {
      "name": "NavAccountCard",
      "kind": "component",
      "signature": "function NavAccountCard(props: NavAccountCardProps): JSX.Element",
      "description": "Sidebar account + logout foot for Navigation footer."
    },
    {
      "name": "NavAccountCardProps",
      "kind": "type",
      "signature": "interface NavAccountCardProps",
      "description": "username, optional nickname/avatar, logoutLabel, onLogout."
    }
  ]
}

import { Avatar } from '../avatar/Avatar.js'
import { Button } from '../button/Button.js'
import './styles.css'

export interface NavAccountCardProps {
  /** Display name (primary line). */
  username: string
  /** Optional secondary line (nickname). */
  nickname?: string
  avatarSrc?: string
  avatarFallback?: string
  /** Logout control label. Default "Log out". */
  logoutLabel?: string
  onLogout?: () => void
  className?: string
}

const logoutIcon = (
  <svg viewBox="0 0 24 24" className="cu-nav-account-card__logout-svg" aria-hidden="true">
    <path
      d="M10 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h5M16 8l4 4-4 4M20 12H10"
      fill="none"
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2}
    />
  </svg>
)

/**
 * Official Navigation sidebar foot: avatar | username/nickname | logout.
 * Mount in Navigation `footer` / `#footer` — sidebar-only (compact TabBar hides it).
 */
export function NavAccountCard({
  username,
  nickname,
  avatarSrc,
  avatarFallback,
  logoutLabel = 'Log out',
  onLogout,
  className,
}: NavAccountCardProps) {
  const classes = ['cu-nav-account-card', className].filter(Boolean).join(' ')
  const fallback = avatarFallback ?? Array.from(username.trim())[0]?.toUpperCase() ?? '?'

  return (
    <div
      className={classes}
      data-ai-role="nav-account-card"
      data-ai-intent="identify-user"
      data-ai-state="default"
    >
      <Avatar
        className="cu-nav-account-card__avatar"
        src={avatarSrc}
        alt={username}
        fallback={fallback}
        size="sm"
      />
      <div className="cu-nav-account-card__text">
        <span className="cu-nav-account-card__username">{username}</span>
        {nickname ? <span className="cu-nav-account-card__nickname">{nickname}</span> : null}
      </div>
      <Button
        className="cu-nav-account-card__logout"
        type="button"
        variant="ghost"
        size="sm"
        icon={logoutIcon}
        onClick={onLogout}
        aria-label={logoutLabel}
      >
        <span className="cu-nav-account-card__logout-label">{logoutLabel}</span>
      </Button>
    </div>
  )
}

/*
 * NavAccountCard — Navigation sidebar account + logout foot.
 * Mount in Navigation footer / #footer. Compact TabBar hides that slot
 * (`.cu-navigation__footer { display: none }` below 48rem).
 *
 * Row height matches NavigationTitle `__frame` (shared chrome formula:
 * --cu-control-size-active + 2 × --cu-space-1).
 */
.cu-nav-account-card {
  display: flex;
  box-sizing: border-box;
  flex-direction: row;
  align-items: center;
  gap: var(--cu-space-2);
  min-inline-size: 0;
  max-inline-size: 100%;
  min-block-size: calc(var(--cu-control-size-active) + 2 * var(--cu-space-1));
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
}

.cu-nav-account-card__avatar {
  flex: none;
}

.cu-nav-account-card__text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  min-inline-size: 0;
}

.cu-nav-account-card__username,
.cu-nav-account-card__nickname {
  min-inline-size: 0;
  max-inline-size: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cu-nav-account-card__username {
  font-size: 0.875rem;
  font-weight: var(--cu-typography-weight-semibold, 600);
  line-height: 1.25;
}

.cu-nav-account-card__nickname {
  font-size: 0.75rem;
  line-height: 1.3;
  color: var(--cu-color-fg-muted, var(--cu-color-fg-default));
  opacity: 0.72;
}

.cu-nav-account-card__logout {
  flex: none;
  margin-inline-start: auto;
}

.cu-nav-account-card__logout-svg {
  inline-size: 1em;
  block-size: 1em;
}

/* Collapsed rail: avatar + icon logout only. */
.cu-navigation--collapsed .cu-nav-account-card {
  flex-direction: column;
  align-items: center;
  gap: var(--cu-space-1);
  padding-inline: var(--cu-space-1);
}

.cu-navigation--collapsed .cu-nav-account-card__text,
.cu-navigation--collapsed .cu-nav-account-card__logout-label {
  display: none;
}

.cu-navigation--collapsed .cu-nav-account-card__logout {
  margin-inline-start: 0;
}
